// Parse and validate decision input
const body = $input.first().json.body;

const required = ['contexto', 'propuesta', 'decision'];
for (const field of required) {
  if (!body[field]) {
    throw new Error(`Campo requerido: ${field}`);
  }
}

const validDecisions = ['sí', 'no', 'después', 'modificar'];
if (!validDecisions.includes(body.decision)) {
  throw new Error(`Decisión inválida. Use: ${validDecisions.join(', ')}`);
}

return [{ json: {
  timestamp: new Date().toISOString(),
  contexto: body.contexto,
  propuesta: body.propuesta,
  decision_usuario: body.decision,
  razon_inferida: body.razon || null,
  patrón_aprendido: null
}}];

// Update memory with new decision
const newDecision = $('Validate Input').first().json;
let memory;

try {
  memory = JSON.parse($('Read Memory').first().json.data);
} catch {
  memory = {
    version: '1.0',
    agent: 'El Operador',
    created: new Date().toISOString(),
    decisions: [],
    learned_patterns: {
      email_preferences: [],
      calendar_preferences: [],
      automation_style: null,
      communication_frequency: 'default'
    },
    statistics: {
      total_proposals: 0,
      accepted: 0,
      rejected: 0,
      deferred: 0,
      modified: 0
    }
  };
}

// Update statistics
memory.statistics.total_proposals++;

switch (newDecision.decision_usuario) {
  case 'sí': memory.statistics.accepted++; break;
  case 'no': memory.statistics.rejected++; break;
  case 'después': memory.statistics.deferred++; break;
  case 'modificar': memory.statistics.modified++; break;
}

// Detect patterns (rule of 3)
const keywords = new Set(newDecision.propuesta.toLowerCase().split(' '));
let similarRejections = 0;

for (const d of memory.decisions.slice(-20)) {
  const dKeywords = new Set(d.propuesta.toLowerCase().split(' '));
  const intersection = [...keywords].filter(x => dKeywords.has(x));
  const overlap = intersection.length / Math.max(keywords.size, 1);

  if (overlap > 0.5 && d.decision_usuario === 'no') {
    similarRejections++;
  }
}

if (similarRejections >= 2 && newDecision.decision_usuario === 'no') {
  newDecision.patrón_aprendido = `Usuario rechaza: ${newDecision.propuesta.substring(0, 50)}...`;
  memory.learned_patterns.email_preferences.push(newDecision.patrón_aprendido);
}

// Add decision
memory.decisions.push(newDecision);

// Keep last 100 decisions
if (memory.decisions.length > 100) {
  memory.decisions = memory.decisions.slice(-100);
}

return [{ json: { memory, newDecision } }];
